import { Method, type MatrixHttpApi, type IHttpOpts } from "../http-api/index.ts";
import { logger } from "../logger.ts";

export interface ServerVersion {
    name: string;
    version: string;
}

export interface ServerCapabilities {
    versions: string[];
    unstableFeatures: Record<string, boolean>;
    maxUploadSize: number;
    defaultHomeserverUrl: string;
}

export interface FeatureSupport {
    encryption: boolean;
    groups: boolean;
    roomVersion: number;
    threadSupport: boolean;
    relatedTypes: boolean;
    externalIds: boolean;
}

export interface CompatibilityResult {
    isCompatible: boolean;
    serverVersion: ServerVersion | null;
    capabilities: ServerCapabilities | null;
    features: FeatureSupport | null;
    issues: string[];
    warnings: string[];
}

export class Compatibility {
    private serverVersion: ServerVersion | null = null;
    private capabilities: ServerCapabilities | null = null;
    private checked = false;

    public constructor(private http: MatrixHttpApi<IHttpOpts>) {}

    public async check(): Promise<CompatibilityResult> {
        const result: CompatibilityResult = {
            isCompatible: true,
            serverVersion: null,
            capabilities: null,
            features: null,
            issues: [],
            warnings: [],
        };

        try {
            const [version, caps] = await Promise.all([this.fetchServerVersion(), this.fetchCapabilities()]);

            result.serverVersion = version;
            result.capabilities = caps;

            result.features = await this.detectFeatures(version, caps);
            result.isCompatible = this.validateCompatibility(result.features, result);

            logger.info(`Compatibility check completed for ${version.name} ${version.version}`);
        } catch (error) {
            const errorObj = error as Error;
            logger.error("Compatibility check failed:", errorObj);
            result.issues.push(`Failed to check compatibility: ${errorObj.message}`);
            result.isCompatible = false;
        }

        this.checked = true;
        return result;
    }

    public async getServerVersion(): Promise<ServerVersion | null> {
        if (!this.serverVersion) {
            try {
                this.serverVersion = await this.fetchServerVersion();
            } catch {
                return null;
            }
        }
        return this.serverVersion;
    }

    public async getCapabilities(): Promise<ServerCapabilities | null> {
        if (!this.capabilities) {
            try {
                this.capabilities = await this.fetchCapabilities();
            } catch {
                return null;
            }
        }
        return this.capabilities;
    }

    public isChecked(): boolean {
        return this.checked;
    }

    public async isFeatureSupported(feature: keyof FeatureSupport): Promise<boolean> {
        if (!this.checked) {
            await this.check();
        }

        if (!this.capabilities || !this.serverVersion) {
            return false;
        }

        const versionNum = this.parseVersion(this.serverVersion.version);

        switch (feature) {
            case "encryption":
                return true;
            case "groups":
                return versionNum >= [1, 6, 0];
            case "threadSupport":
                return this.capabilities.unstableFeatures["org.matrix.msc3440_threads"] ?? false;
            case "relatedTypes":
                return this.capabilities.unstableFeatures["org.matrix.msc2675"] ?? false;
            case "externalIds":
                return versionNum >= [1, 1, 0];
            default:
                return false;
        }
    }

    public async getRequiredRoomVersion(): Promise<number> {
        const caps = await this.getCapabilities();
        if (!caps) {
            return 1;
        }

        return caps.unstableFeatures["require_tfa_for_user_management"] ? 6 : 1;
    }

    public async validateRoomVersion(roomVersion: number): Promise<boolean> {
        const caps = await this.getCapabilities();
        if (!caps) {
            return false;
        }

        const supportedVersions = caps.versions.filter((v) => v.startsWith("v"));
        const maxVersion = supportedVersions.reduce(
            (max, v) => {
                const num = this.parseVersion(v);
                return num > max ? num : max;
            },
            [1, 0, 0],
        );

        const requestedVersion = Array.isArray(roomVersion) ? roomVersion : [roomVersion, 0, 0];

        return requestedVersion <= maxVersion;
    }

    private async fetchServerVersion(): Promise<ServerVersion> {
        const response = await this.http.authedRequest<{
            server?: { version?: string };
            versions?: string[];
        }>(Method.Get, "/_matrix/client/versions");

        if (response.server?.version) {
            const [name, version] = response.server.version.split(" ");
            return { name: name ?? "unknown", version: version ?? "0.0.0" };
        }

        if (response.versions && response.versions.length > 0) {
            return { name: "matrix", version: response.versions[0] };
        }

        return { name: "unknown", version: "0.0.0" };
    }

    private async fetchCapabilities(): Promise<ServerCapabilities> {
        try {
            const response = await this.http.authedRequest<{
                capabilities?: {
                    "m.change_password"?: { enabled?: boolean };
                    "m.room_versions"?: { available?: Record<string, { version?: string }> };
                    "m.upload_size"?: { limit?: number };
                };
            }>(Method.Get, "/_matrix/client/r0/capabilities");

            const roomVersions = response.capabilities?.["m.room_versions"]?.available ?? {};
            const versions = Object.keys(roomVersions).filter((v) => v.startsWith("v"));

            const uploadSizeCap = response.capabilities as Record<string, unknown> | undefined;
            const mUploadSize = uploadSizeCap?.["m.upload_size"] as { limit?: number } | undefined;

            return {
                versions,
                unstableFeatures: {},
                maxUploadSize: mUploadSize?.limit ?? 50000000,
                defaultHomeserverUrl: "",
            };
        } catch {
            return {
                versions: ["v1", "v2", "v3", "v4", "v5", "v6"],
                unstableFeatures: {},
                maxUploadSize: 50000000,
                defaultHomeserverUrl: "",
            };
        }
    }

    private async detectFeatures(version: ServerVersion, capabilities: ServerCapabilities): Promise<FeatureSupport> {
        const versionNum = this.parseVersion(version.version);

        return {
            encryption: versionNum >= [1, 0, 0],
            groups: versionNum >= [1, 6, 0],
            roomVersion: versionNum[0],
            threadSupport: capabilities.unstableFeatures["org.matrix.msc3440_threads"] ?? false,
            relatedTypes: capabilities.unstableFeatures["org.matrix.msc2675"] ?? false,
            externalIds: versionNum >= [1, 1, 0],
        };
    }

    private validateCompatibility(features: FeatureSupport, result: CompatibilityResult): boolean {
        if (!features.encryption) {
            result.issues.push("Server does not support end-to-end encryption");
            return false;
        }

        if (features.roomVersion < 1) {
            result.warnings.push("Unknown room version support");
        }

        return true;
    }

    private parseVersion(version: string): number[] {
        const parts = version.split(/[-+]/)[0].split(".").map(Number);
        while (parts.length < 3) {
            parts.push(0);
        }
        return parts.slice(0, 3) as [number, number, number];
    }
}
